 3→/**
 4→ * Helper: create an index, ignoring if it already exists.
 5→ * Vitess doesn't support CREATE INDEX IF NOT EXISTS, so we catch the error.
 6→ * MySQL error 1061 = "Duplicate key name".
 7→ */
 8→async function createIndexIfNotExists(
 9→  db: Kysely<unknown>,
10→  indexName: string,
11→  table: string,
12→  columns: string[],
13→) {
14→  try {
15→    await db.schema
16→      .createIndex(indexName)
17→      .on(table)
18→      .columns(columns)
19→      .execute();
20→  } catch (e: unknown) {
21→    const msg = e instanceof Error ? e.message : "";
22→    if (msg.includes("Duplicate key name") || msg.includes("already exists"))
23→      return;
24→    throw e;
25→  }
26→}
