  1→// Search index queue consumer
  2→// Processes checkpoint indexing messages for Turbopuffer vector search
  3→
  4→import type { Env } from "../env";
  5→import { getDb } from "./db";
  6→import { indexCheckpoints } from "./turbopuffer";
  7→import { avgMs, generateBatchId } from "./telemetry";
  8→import { getInstallationToken } from "./token";
  9→import { fetchFileAtCommit } from "./github";
 10→import { getParserForAgent } from "./transcript-parsers/registry";
 11→import { CHECKPOINT_BRANCH } from "./constants";
 12→
 13→const MAX_TRANSCRIPT_CHARS = 200_000;
 14→const TRANSCRIPT_CONCURRENCY = 10;
 15→
 16→// Queue message sent after checkpoint data is upserted into PlanetScale
 17→export interface SearchIndexMessage {
 18→  repoId: string;
 19→  checkpointIds: string[];
 20→  queuedAt: string;
 21→}
 22→
 23→// Type guard to check if a message is a SearchIndexMessage
 24→export function isSearchIndexMessage(
 25→  msg: unknown,
 26→): msg is SearchIndexMessage {
 27→  return (
 28→    typeof msg === "object" &&
 29→    msg !== null &&
 30→    "repoId" in msg &&
 31→    "checkpointIds" in msg &&
 32→    "queuedAt" in msg &&
 33→    typeof (msg as SearchIndexMessage).repoId === "string" &&
 34→    Array.isArray((msg as SearchIndexMessage).checkpointIds)
 35→  );
 36→}
 37→
 38→// Log with consistent prefix
 39→function log(event: string, data: Record<string, unknown>): void {
 40→  console.log(`[search-index-queue] ${event}`, JSON.stringify(data));
 41→}
 42→
 43→// Fetch and parse transcript for a checkpoint, returning user prompts + assistant responses
 44→async function fetchTranscriptExcerpt(
 45→  repoFullName: string,
 46→  checkpointId: string,
 47→  agent: string,
 48→  token: string,
 49→): Promise<string | null> {
 50→  try {
 51→    const folder = `${checkpointId.slice(0, 2)}/${checkpointId.slice(2)}`;
 52→    const path = `${folder}/0/full.jsonl`;
 53→
 54→    const content = await fetchFileAtCommit(repoFullName, path, CHECKPOINT_BRANCH, token);
 55→    if (!content) return null;
 56→
 57→    const parser = getParserForAgent(agent);
 58→    const result = parser.parse(content);
 59→    if (result.messages.length === 0) return null;
 60→
 61→    // Extract user prompts + assistant responses, skip tool-only messages
 62→    const parts: string[] = [];
 63→    let charsUsed = 0;
 64→
 65→    for (const msg of result.messages) {
 66→      if (charsUsed >= MAX_TRANSCRIPT_CHARS) break;
 67→      if (msg.role === "assistant" && msg.toolCalls?.length && !msg.content.trim()) continue;
 68→
 69→      const remaining = MAX_TRANSCRIPT_CHARS - charsUsed;
 70→      const text = msg.content.slice(0, remaining);
 71→      parts.push(`[${msg.role}]: ${text}`);
 72→      charsUsed += text.length;
 73→    }
 74→
 75→    return parts.join("\n") || null;
 76→  } catch {
 77→    return null;
 78→  }
 79→}
 80→
 81→// Process a batch of search index messages
 82→export async function processSearchIndexBatch(
 83→  batch: MessageBatch<SearchIndexMessage>,
 84→  env: Env,
 85→): Promise<void> {
 86→  const batchStartTime = Date.now();
 87→  const batchId = generateBatchId();
 88→
 89→  const queueWaitTimes = batch.messages.map(
 90→    (msg) => Date.now() - msg.timestamp.getTime(),
 91→  );
 92→  const maxWaitMs = queueWaitTimes.length > 0 ? Math.max(...queueWaitTimes) : 0;
 93→
 94→  log("batch_started", {
 95→    batchId,
 96→    queue: batch.queue,
 97→    count: batch.messages.length,
 98→    avgQueueWaitMs: avgMs(queueWaitTimes),
 99→    maxQueueWaitMs: maxWaitMs,
100→  });
101→
102→  const processingTimes: number[] = [];
103→  let successCount = 0;
104→  let errorCount = 0;
105→  let skippedCount = 0;
106→
107→  for (const msg of batch.messages) {
108→    const msgStartTime = Date.now();
109→    const { repoId, checkpointIds } = msg.body;
110→
111→    // Early return if API keys are missing — don't retry messages that can never succeed
112→    if (!env.TURBOPUFFER_API_KEY || !env.OPENAI_API_KEY) {
113→      log("skip_missing_api_keys", {
114→        batchId,
115→        repoId,
116→        hasTurbopuffer: !!env.TURBOPUFFER_API_KEY,
117→        hasOpenai: !!env.OPENAI_API_KEY,
118→      });
119→      msg.ack();
120→      skippedCount++;
121→      continue;
122→    }
123→
124→    try {
125→      const db = getDb(env);
126→
127→      const repo = await db.repos.getById(repoId);
128→      if (!repo) {
129→        log("skip_repo_not_found", { batchId, repoId });
130→        msg.ack();
131→        skippedCount++;
132→        continue;
133→      }
134→
135→      const checkpoints = await db.checkpoints.getByIds(repoId, checkpointIds);
136→
137→      if (checkpoints.length === 0) {
138→        log("skip_no_checkpoints", { batchId, repoId, requestedIds: checkpointIds.length });
139→        msg.ack();
140→        skippedCount++;
141→        continue;
142→      }
143→
144→      // Fetch transcripts from GitHub (best-effort, non-blocking)
145→      const transcripts = new Map<string, string | null>();
146→      if (repo.installation_id) {
147→        try {
148→          const token = await getInstallationToken(
149→            Number(repo.installation_id),
150→            { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
151→            env.ENTIRE_CACHE,
152→          );
153→
154→          // Fetch in parallel with concurrency limit
155→          for (let i = 0; i < checkpoints.length; i += TRANSCRIPT_CONCURRENCY) {
156→            const batch = checkpoints.slice(i, i + TRANSCRIPT_CONCURRENCY);
157→            const results = await Promise.all(
158→              batch.map((cp) =>
159→                fetchTranscriptExcerpt(repo.full_name, cp.checkpoint_id, cp.agent ?? "Claude Code", token),
160→              ),
161→            );
162→            for (let j = 0; j < results.length; j++) {
163→              transcripts.set(batch[j].checkpoint_id, results[j]);
164→            }
165→          }
166→        } catch (err) {
167→          log("transcript_fetch_error", {
168→            batchId,
169→            repoId,
170→            error: err instanceof Error ? err.message : String(err),
171→          });
172→          // Continue without transcripts — prompt/commit/files still get indexed
173→        }
174→      }
175→
176→      const indexed = await indexCheckpoints(
177→        env.TURBOPUFFER_API_KEY,
178→        env.OPENAI_API_KEY,
179→        repo.github_id,
180→        checkpoints.map((cp) => ({
181→          checkpoint_id: cp.checkpoint_id,
182→          branch: cp.branch,
183→          agent: cp.agent,
184→          commit_author_username: cp.commit_author_username,
185→          created_at: cp.created_at,
186→          commit_sha: cp.commit_sha,
187→          commit_message: cp.commit_message,
188→          prompt: cp.prompt,
189→          files_touched: cp.files_touched,
190→          transcript: transcripts.get(cp.checkpoint_id) ?? null,
191→        })),
192→      );
193→
194→      const processingMs = Date.now() - msgStartTime;
195→      processingTimes.push(processingMs);
196→
197→      log("message_processed", {
198→        batchId,
199→        repoId,
200→        requested: checkpointIds.length,
201→        found: checkpoints.length,
202→        indexed,
203→        processingMs,
204→        attempt: msg.attempts,
205→      });
206→
207→      msg.ack();
208→      successCount++;
209→    } catch (err) {
210→      const processingMs = Date.now() - msgStartTime;
211→      processingTimes.push(processingMs);
212→      errorCount++;
213→
214→      log("message_error", {
215→        batchId,
216→        repoId,
217→        checkpointCount: checkpointIds.length,
218→        attempt: msg.attempts,
219→        processingMs,
220→        error: err instanceof Error ? err.message : String(err),
221→      });
222→
223→      // Retry on transient failures (max_retries configured in wrangler.jsonc)
224→      msg.retry();
225→    }
226→  }
227→
228→  const totalBatchTimeMs = Date.now() - batchStartTime;
229→
230→  log("batch_complete", {
231→    batchId,
232→    count: batch.messages.length,
233→    successCount,
234→    errorCount,
235→    skippedCount,
236→    totalBatchTimeMs,
237→    avgProcessingMs: avgMs(processingTimes),
238→    throughputPerMin:
239→      totalBatchTimeMs > 0
240→        ? Math.round((batch.messages.length / totalBatchTimeMs) * 60000)
241→        : 0,
242→  });
243→}
