  1→// Repo-level checkpoint sync service
  2→// Syncs checkpoints for a single repository (shared across all users)
  3→// Uses CHECKPOINT_BRANCH as source of truth for checkpoint discovery
  4→
  5→import {
  6→  checkBranchExists,
  7→  discoverCheckpointsFromBranch,
  8→  fetchCommitStatsBatch,
  9→  fetchSessionDataBatch,
 10→  parseSquashCommitTitles,
 11→  GitHubRateLimitError,
 12→  discoverTrailsFromBranch,
 13→  fetchTrailDataBatch,
 14→} from "./github";
 15→import { CHECKPOINT_BRANCH, TRAILS_BRANCH } from "./constants";
 16→import { getValidGitHubToken } from "./token";
 17→import type { Db } from "./db/db-types";
 18→import type { Json, RepoTrailInsert } from "../types/database";
 19→import type { Trail } from "../types";
 20→import { errorString } from "./telemetry";
 21→
 22→const LOG_PREFIX = "[repo-sync]";
 23→
 24→// Log with consistent prefix
 25→function log(event: string, data: Record<string, unknown>): void {
 26→  console.log(`${LOG_PREFIX} ${event}`, JSON.stringify(data));
 27→}
 28→
 29→// Queue message for repo checkpoint sync
 30→export interface RepoSyncMessage {
 31→  repoId: string;
 32→  reason: "installation" | "reconciliation" | "manual" | "user_sync";
 33→  priority: number; // 10 = immediate (installation, user_sync), 5 = manual, 1 = reconciliation
 34→  queuedAt: string;
 35→}
 36→
 37→// Result of syncing a repo
 38→export interface RepoSyncResult {
 39→  status: "ok" | "skipped" | "error";
 40→  reason?: string;
 41→  checkpointsDiscovered?: number;
 42→  checkpointsWithCommits?: number;
 43→  isBackfill?: boolean;
 44→}
 45→
 46→// Re-export shared types and dedup functions for backward compatibility
 47→export type { CheckpointData, CommitData } from "./db/sync-types";
 48→export { deduplicateCheckpoints, deduplicateCommits } from "./db/sync-types";
 49→import type { CheckpointData, CommitData } from "./db/sync-types";
 50→
 51→// Sync checkpoints for a single repo
 52→// Called by queue consumer
 53→export async function syncRepoCheckpoints(
 54→  db: Db,
 55→  repoId: string,
 56→  token: string,
 57→  options: { fullBackfill?: boolean; skipAppInstallationCheck?: boolean; extraBranches?: string[] } = {}
 58→): Promise<RepoSyncResult> {
 59→  const repoData = await db.repos.getById(repoId);
 60→
 61→  if (!repoData) {
 62→    return { status: "skipped", reason: "repo_not_found" };
 63→  }
 64→
 65→  // Apply defaults for fields that may be null in the database
 66→  const repo = {
 67→    ...repoData,
 68→    default_branch: repoData.default_branch ?? "main",
 69→    app_has_access: repoData.app_has_access ?? false,
 70→  };
 71→
 72→  // Skip app installation check when explicitly requested (e.g., local dev "Fetch from GitHub" button)
 73→  // In local dev, webhooks don't fire so app_has_access is never set
 74→  if (!repo.app_has_access && !options.skipAppInstallationCheck) {
 75→    return { status: "skipped", reason: "no_app_access" };
 76→  }
 77→
 78→  // Check if CHECKPOINT_BRANCH exists (quick "is this repo Entire-enabled?" check)
 79→  const branchExists = await checkBranchExists(repo.full_name, CHECKPOINT_BRANCH, token);
 80→  if (branchExists === null) {
 81→    return { status: "skipped", reason: "branch_check_error" };
 82→  }
 83→  if (branchExists === false) {
 84→    await db.checkpoints.updateSyncState(repoId, {});
 85→    return { status: "skipped", reason: "no_sessions_branch" };
 86→  }
 87→
 88→  const isBackfill = !repo.checkpoints_backfilled_at || options.fullBackfill;
 89→  const since = isBackfill ? undefined : (repo.checkpoints_sync_cursor ?? undefined);
 90→
 91→  log("sync_started", {
 92→    repoId,
 93→    fullName: repo.full_name,
 94→    isBackfill,
 95→    since,
 96→  });
 97→
 98→  try {
 99→    // Step 1: Discover checkpoints from default branch via Entire-Checkpoint trailers
100→    const discovered = await discoverCheckpointsFromBranch(
101→      repo.full_name,
102→      repo.default_branch,
103→      token,
104→      since
105→    );
106→
107→    // Track which branch each checkpoint was discovered on (for commit data)
108→    const discoveredBranch = new Map<string, string>();
109→    for (const d of discovered) {
110→      discoveredBranch.set(d.checkpointId, repo.default_branch);
111→    }
112→
113→    // Also scan extra branches (e.g., local dev where webhooks don't fire)
114→    // No `since` filter — cursor is from the default branch and doesn't apply here
115→    const extraBranches = (options.extraBranches ?? []).filter(
116→      (b) => b !== repo.default_branch
117→    );
118→    for (const branch of extraBranches) {
119→      const branchDiscovered = await discoverCheckpointsFromBranch(
120→        repo.full_name,
121→        branch,
122→        token
123→      );
124→      log("extra_branch_scan", {
125→        repoId,
126→        branch,
127→        found: branchDiscovered.length,
128→        alreadyKnown: branchDiscovered.filter((d) => discoveredBranch.has(d.checkpointId)).length,
129→      });
130→      for (const d of branchDiscovered) {
131→        if (!discoveredBranch.has(d.checkpointId)) {
132→          discovered.push(d);
133→          discoveredBranch.set(d.checkpointId, branch);
134→        }
135→      }
136→    }
137→
138→    if (discovered.length === 0) {
139→      await db.checkpoints.updateSyncState(repoId, {});
140→      if (isBackfill) {
141→        await db.checkpoints.updateSyncState(repoId, { backfilled: true });
142→      }
143→      log("sync_complete_no_checkpoints", { repoId, fullName: repo.full_name });
144→      return { status: "ok", checkpointsDiscovered: 0, isBackfill };
145→    }
146→
147→    const checkpointIds = discovered.map((d) => d.checkpointId);
148→    // Cursor: latest commit date from the default branch only
149→    // Extra branches may have different dates that shouldn't affect the default branch cursor
150→    const defaultBranchDiscovered = discovered.filter(
151→      (d) => discoveredBranch.get(d.checkpointId) === repo.default_branch
152→    );
153→    const latestCursor = defaultBranchDiscovered[0]?.commit.date;
154→
155→    log("checkpoints_discovered", {
156→      repoId,
157→      fullName: repo.full_name,
158→      count: checkpointIds.length,
159→    });
160→
161→    // Step 2: Fetch session metadata from CHECKPOINT_BRANCH tree
162→    const sessionDataResult = await fetchSessionDataBatch(repo.full_name, checkpointIds, token);
163→
164→    if (sessionDataResult.failedItems.length > 0) {
165→      log("session_data_partial_failure", {
166→        repoId,
167→        failed: sessionDataResult.failedItems.length,
168→      });
169→    }
170→
171→    // Step 3: Upsert checkpoint metadata (before commits due to FK constraint)
172→    const checkpointData: CheckpointData[] = checkpointIds.map((cpId) => {
173→      const session = sessionDataResult.data.get(cpId);
174→      return {
175→        checkpoint_id: cpId,
176→        prompt: session?.prompt ?? null,
177→        agent: session?.agent ?? null,
178→        steps: session?.steps ?? null,
179→        session_count: session?.sessionCount ?? null,
180→        strategy: session?.strategy ?? null,
181→        branch: session?.branch ?? null,
182→        session_id: session?.sessionId ?? null,
183→        files_touched: session?.filesTouched ? JSON.stringify(session.filesTouched) : null,
184→        session_ids: session?.sessionIds ? JSON.stringify(session.sessionIds) : null,
185→        transcript_uuid_at_start: session?.transcriptUuidAtStart ?? null,
186→        transcript_lines_at_start: session?.transcriptLinesAtStart ?? null,
187→        checkpoint_transcript_start: session?.checkpointTranscriptStart ?? null,
188→        input_tokens: session?.inputTokens ?? null,
189→        cache_creation_tokens: session?.cacheCreationTokens ?? null,
190→        cache_read_tokens: session?.cacheReadTokens ?? null,
191→        output_tokens: session?.outputTokens ?? null,
192→        api_call_count: session?.apiCallCount ?? null,
193→        sessions: session?.sessions ? JSON.stringify(session.sessions) : null,
194→        created_at: session?.createdAt ?? new Date().toISOString(),
195→      };
196→    });
197→
198→    await db.checkpoints.upsertSyncCheckpointBatch(repoId, checkpointData);
199→
200→    // Step 4: Upsert commit data (commit info already available from discovery)
201→    // For non-backfill, skip checkpoints that already have commits on their respective branch
202→    let discoveredToProcess = discovered;
203→
204→    if (!isBackfill) {
205→      // Group checkpoints by branch to check per-branch commit existence
206→      const checkpointsByBranch = new Map<string, string[]>();
207→      for (const d of discovered) {
208→        const branch = discoveredBranch.get(d.checkpointId) ?? repo.default_branch;
209→        const existing = checkpointsByBranch.get(branch) ?? [];
210→        existing.push(d.checkpointId);
211→        checkpointsByBranch.set(branch, existing);
212→      }
213→
214→      // Check which checkpoints already have commits on their respective branch
215→      const existingWithCommitsOnBranch = new Set<string>();
216→      for (const [branch, cpIds] of checkpointsByBranch) {
217→        const existingOnBranch = await db.checkpoints.getIdsWithCommits(repoId, cpIds, branch);
218→        for (const cpId of existingOnBranch) {
219→          existingWithCommitsOnBranch.add(cpId);
220→        }
221→      }
222→
223→      if (existingWithCommitsOnBranch.size > 0) {
224→        discoveredToProcess = discovered.filter(
225→          (d) => !existingWithCommitsOnBranch.has(d.checkpointId)
226→        );
227→
228→        log("reconciliation_optimization", {
229→          repoId,
230→          totalCheckpoints: checkpointIds.length,
231→          alreadyHaveCommits: existingWithCommitsOnBranch.size,
232→          needToProcess: discoveredToProcess.length,
233→        });
234→      }
235→    }
236→
237→    let commitsFound = 0;
238→
239→    if (discoveredToProcess.length > 0) {
240→      // Fetch commit stats for new checkpoints
241→      const shas = discoveredToProcess.map((d) => d.commit.sha);
242→      const statsResult = await fetchCommitStatsBatch(repo.full_name, shas, token);
243→
244→      // Parse squash commit titles for each unique commit message
245→      const squashTitlesByMessage = new Map<string, Map<string, string>>();
246→      for (const d of discoveredToProcess) {
247→        if (!squashTitlesByMessage.has(d.commit.message)) {
248→          squashTitlesByMessage.set(d.commit.message, parseSquashCommitTitles(d.commit.message));
249→        }
250→      }
251→
252→      const commitData: CommitData[] = discoveredToProcess.map((d) => {
253→        const stats = statsResult.data.get(d.commit.sha);
254→        const squashTitles = squashTitlesByMessage.get(d.commit.message);
255→        const commitTitle = squashTitles?.get(d.checkpointId) ?? d.commit.message.split("\n")[0];
256→        return {
257→          checkpoint_id: d.checkpointId,
258→          branch: discoveredBranch.get(d.checkpointId) ?? repo.default_branch,
259→          commit_sha: d.commit.sha,
260→          commit_message: commitTitle,
261→          commit_author: d.commit.author,
262→          commit_author_username: d.commit.authorUsername ?? null,
263→          commit_author_github_id: d.commit.authorId ?? null,
264→          commit_date: d.commit.date,
265→          additions: stats?.additions ?? 0,
266→          deletions: stats?.deletions ?? 0,
267→          files_changed: stats?.filesChanged ?? 0,
268→          file_stats: stats?.files ?? null,
269→        };
270→      });
271→
272→      commitsFound = await db.checkpoints.upsertSyncCommitBatch(repoId, commitData);
273→
274→      log("commits_processed", {
275→        repoId,
276→        branch: repo.default_branch,
277→        commitsFound,
278→      });
279→    }
280→
281→    // Step 5: Reconcile stale checkpoint commits (backfill only)
282→    // During a full backfill we have the complete picture of what's on each branch,
283→    // so we can safely remove checkpoint commits that are no longer reachable
284→    // (e.g., after force pushes that rewrote history).
285→    let staleDeleted = 0;
286→    if (isBackfill) {
287→      // Group discovered checkpoint IDs by branch
288→      const validByBranch = new Map<string, string[]>();
289→      for (const d of discovered) {
290→        const branch = discoveredBranch.get(d.checkpointId) ?? repo.default_branch;
291→        const existing = validByBranch.get(branch) ?? [];
292→        existing.push(d.checkpointId);
293→        validByBranch.set(branch, existing);
294→      }
295→
296→      // Reconcile each branch we scanned
297→      const branchesToReconcile = new Set([repo.default_branch, ...extraBranches]);
298→      for (const branch of branchesToReconcile) {
299→        const validIds = validByBranch.get(branch) ?? [];
300→        const deleted = await db.checkpoints.deleteStaleCommitsForBranch(repoId, branch, validIds);
301→        staleDeleted += deleted;
302→      }
303→
304→      if (staleDeleted > 0) {
305→        await db.checkpoints.deleteOrphaned(repoId);
306→        log("stale_commits_reconciled", { repoId, staleDeleted });
307→      }
308→    }
309→
310→    // Step 6: Update sync state
311→    await db.checkpoints.updateSyncState(repoId, {
312→      cursor: latestCursor,
313→      backfilled: isBackfill,
314→    });
315→
316→    // Step 6: Recalculate checkpoint count
317→    await db.checkpoints.recalculateCount(repoId);
318→
319→    const totalSessions = checkpointData.reduce((sum, cp) => sum + (cp.session_count ?? 0), 0);
320→    const checkpointsWithSessions = checkpointData.filter((cp) => cp.sessions != null).length;
321→
322→    log("sync_complete", {
323→      repoId,
324→      fullName: repo.full_name,
325→      checkpointsDiscovered: checkpointIds.length,
326→      checkpointsWithCommits: commitsFound,
327→      totalSessions,
328→      checkpointsWithSessions,
329→      isBackfill,
330→    });
331→
332→    return {
333→      status: "ok",
334→      checkpointsDiscovered: checkpointIds.length,
335→      checkpointsWithCommits: commitsFound,
336→      isBackfill,
337→    };
338→  } catch (err) {
339→    if (err instanceof GitHubRateLimitError) {
340→      throw err;
341→    }
342→
343→    const errorMessage = errorString(err);
344→    await db.checkpoints.updateSyncState(repoId, { error: errorMessage });
345→
346→    log("sync_error", {
347→      repoId,
348→      fullName: repo.full_name,
349→      error: errorMessage,
350→    });
351→
352→    return { status: "error", reason: errorMessage };
353→  }
354→}
