356→// Cloudflare Queue sendBatch limits
357→const QUEUE_BATCH_MAX_MESSAGES = 100;
358→
359→// Queue multiple repos for checkpoint sync using sendBatch
360→// Respects Cloudflare Queue limits: max 100 messages per batch
361→export async function queueRepoSyncBatch(
362→  queue: Queue<RepoSyncMessage>,
363→  repos: { id: string }[],
364→  reason: RepoSyncMessage["reason"],
365→  priority: number = 5
366→): Promise<number> {
367→  if (repos.length === 0) return 0;
368→
369→  const queuedAt = new Date().toISOString();
370→  let totalQueued = 0;
371→
372→  // Process in batches of 100 (Cloudflare Queue limit)
373→  for (let i = 0; i < repos.length; i += QUEUE_BATCH_MAX_MESSAGES) {
374→    const batch = repos.slice(i, i + QUEUE_BATCH_MAX_MESSAGES);
375→    const messages = batch.map((repo) => ({
376→      body: {
377→        repoId: repo.id,
378→        reason,
379→        priority,
380→        queuedAt,
381→      },
382→    }));
383→
384→    await queue.sendBatch(messages);
385→    totalQueued += batch.length;
386→  }
387→
388→  log("repos_queued_batch", { count: totalQueued, reason, priority, batches: Math.ceil(repos.length / QUEUE_BATCH_MAX_MESSAGES) });
389→  return totalQueued;
390→}
