401→// Result of syncing checkpoints for a user
402→export interface UserCheckpointSyncResult {
403→  reposChecked: number;
404→  reposWithAccess: number;
405→  reposSynced: number;
406→  errors: number;
407→}
408→
409→// Sync checkpoints for all repos a user has access to
410→// This is the repo-centric replacement for the legacy syncCheckpointsForUser
411→export async function syncCheckpointsForUser(
412→  userId: string,
413→  env: CheckpointSyncEnv
414→): Promise<UserCheckpointSyncResult> {
415→  const result: UserCheckpointSyncResult = {
416→    reposChecked: 0,
417→    reposWithAccess: 0,
418→    reposSynced: 0,
419→    errors: 0,
420→  };
421→
422→  // Get user and their token
423→  const user = await env.db.users.findById(userId);
424→
425→  if (!user || !user.github_token_enc) {
426→    log("skip_no_token", { userId });
427→    return result;
428→  }
429→
430→  // Get valid token
431→  let token: string;
432→  try {
433→    const tokenResult = await getValidGitHubToken(env.db, user, {
434→      clientId: env.clientId,
435→      clientSecret: env.clientSecret,
436→      encryptionKey: env.encryptionKey,
437→    }, env.cache);
438→    token = tokenResult.token;
439→  } catch (err) {
440→    log("token_error", { userId, error: errorString(err) });
441→    return result;
442→  }
443→
444→  // Get all repos for this user from the repo-centric schema
445→  const repos = await env.db.repos.getForUser(userId);
446→  result.reposChecked = repos.length;
447→
448→  log("user_sync_started", {
449→    userId,
450→    totalRepos: repos.length,
451→  });
452→
453→  // Filter to repos where app has access
454→  const accessibleRepos = repos.filter((r) => r.app_has_access);
455→  result.reposWithAccess = accessibleRepos.length;
456→
457→  // Process repos in batches to avoid rate limits
458→  const BATCH_SIZE = 5;
459→  for (let i = 0; i < accessibleRepos.length; i += BATCH_SIZE) {
460→    const batch = accessibleRepos.slice(i, i + BATCH_SIZE);
461→
462→    await Promise.all(
463→      batch.map(async (repo) => {
464→        try {
465→          const syncResult = await syncRepoCheckpoints(env.db, repo.id, token);
466→          if (syncResult.status === "ok") {
467→            result.reposSynced++;
468→          }
469→        } catch (err) {
470→          result.errors++;
471→          log("repo_sync_error", {
472→            repoId: repo.id,
473→            fullName: repo.full_name,
474→            error: errorString(err),
475→          });
476→        }
477→      })
478→    );
479→  }
480→
481→  log("user_sync_completed", { userId, ...result });
482→  return result;
483→}
