496→/**
497→ * Sync trails for a repository
498→ * Discovers trails from entire/trails/v1 branch and upserts to database
499→ */
500→export async function syncRepoTrails(
501→  db: Db,
502→  repoId: string,
503→  repoFullName: string,
504→  token: string,
505→): Promise<TrailSyncResult> {
506→  log("trails_sync_start", { repoId, repoFullName });
507→
508→  // Check if trails branch exists
509→  const branchExists = await checkBranchExists(repoFullName, TRAILS_BRANCH, token);
510→  if (!branchExists) {
511→    log("trails_sync_skip", { repoId, reason: "no_trails_branch" });
512→    return { status: "skipped", reason: "no_trails_branch" };
513→  }
514→
515→  // Discover all trail IDs
516→  const trailIds = await discoverTrailsFromBranch(repoFullName, token);
517→  if (trailIds.length === 0) {
518→    log("trails_sync_skip", { repoId, reason: "no_trails" });
519→    return { status: "skipped", reason: "no_trails" };
520→  }
521→
522→  log("trails_discovered", { repoId, count: trailIds.length });
523→
524→  // Fetch trail data in batches
525→  const trailData = await fetchTrailDataBatch(repoFullName, trailIds, token);
526→
527→  // Upsert trails to database
528→  let synced = 0;
529→  for (const [trailId, trail] of trailData) {
530→    try {
531→      await upsertTrail(db, repoId, trail);
532→      synced++;
533→    } catch (err) {
534→      log("trail_upsert_error", {
535→        repoId,
536→        trailId,
537→        error: errorString(err),
538→      });
539→    }
540→  }
541→
542→  log("trails_sync_completed", {
543→    repoId,
544→    discovered: trailIds.length,
545→    synced,
546→  });
547→
548→  return {
549→    status: "ok",
550→    trailsDiscovered: trailIds.length,
551→    trailsSynced: synced,
552→  };
553→}
