555→/**
556→ * Upsert a trail to the database.
557→ * Uses the optional trails namespace (available on Supabase, not yet on PlanetScale).
558→ */
559→async function upsertTrail(
560→  db: Db,
561→  repoId: string,
562→  trail: Trail,
563→): Promise<void> {
564→  if (!db.trails) {
565→    // PlanetScale doesn't have repo_trails table yet - skip DB sync
566→    return;
567→  }
568→
569→  const { metadata, discussion } = trail;
570→
571→  // Calculate comment counts
572→  let commentCount = 0;
573→  let unresolvedCount = 0;
574→  for (const comment of discussion.comments ?? []) {
575→    commentCount += 1 + (comment.replies?.length ?? 0);
576→    if (!comment.resolved) {
577→      unresolvedCount++;
578→    }
579→  }
580→
581→  const row: RepoTrailInsert = {
582→    repo_id: repoId,
583→    trail_id: metadata.trail_id,
584→    branch: metadata.branch,
585→    base: metadata.base,
586→    title: metadata.title,
587→    body: metadata.body || null,
588→    status: metadata.status,
589→    author: metadata.author,
590→    assignees: metadata.assignees,
591→    labels: metadata.labels,
592→    created_at: metadata.created_at,
593→    updated_at: metadata.updated_at,
594→    merged_at: metadata.merged_at,
595→    discussion: discussion as unknown as Json,
596→    comment_count: commentCount,
597→    unresolved_count: unresolvedCount,
598→  };
599→
600→  await db.trails.upsert(row);
601→}
