101→// Type guard to check if a message is a RepoSyncMessage
102→export function isRepoSyncMessage(msg: unknown): msg is RepoSyncMessage {
103→  return (
104→    typeof msg === "object" &&
105→    msg !== null &&
106→    "repoId" in msg &&
107→    "reason" in msg &&
108→    "priority" in msg &&
109→    "queuedAt" in msg &&
110→    typeof (msg as RepoSyncMessage).repoId === "string" &&
111→    typeof (msg as RepoSyncMessage).reason === "string" &&
112→    typeof (msg as RepoSyncMessage).priority === "number"
113→  );
114→}
