116→// Look up the GitHub App installation ID for a repo
117→async function getRepoInstallationId(
118→  db: Db,
119→  repoId: string,
120→): Promise<number | null> {
121→  const repo = await db.repos.getById(repoId);
122→
123→  if (!repo) {
124→    log("repo_not_found", { repoId });
125→    return null;
126→  }
127→
128→  // Fast path: use the direct FK if available
129→  if (repo.installation_id) {
130→    const githubInstallationId = await db.installations.getGithubId(repo.installation_id);
131→    if (githubInstallationId) {
132→      return githubInstallationId;
133→    }
134→  }
135→
136→  // NB: This fallback shouldn't be required for long.
137→  // Fallback: look up by owner name (for repos not yet backfilled)
138→  const owner = repo.full_name.split("/")[0];
139→  const githubInstallationId = await db.installations.getGithubIdByOwner(owner);
140→  if (!githubInstallationId) {
141→    log("no_installation_for_repo", { repoId, owner });
142→    return null;
143→  }
144→
145→  return githubInstallationId;
146→}
