171→// Process a batch of repo sync messages
172→export async function processRepoSyncBatch(
173→  batch: MessageBatch<RepoSyncMessage>,
174→  env: Env,
175→): Promise<void> {
176→  const batchStartTime = Date.now();
177→  const batchId = generateBatchId();
178→
179→  // Calculate queue wait times for all messages in batch
180→  const queueWaitTimes = batch.messages.map(
181→    (msg) => Date.now() - msg.timestamp.getTime(),
182→  );
183→  const maxWaitMs = queueWaitTimes.length > 0 ? Math.max(...queueWaitTimes) : 0;
184→
185→  log("batch_started", {
186→    batchId,
187→    queue: batch.queue,
188→    count: batch.messages.length,
189→    avgQueueWaitMs: avgMs(queueWaitTimes),
190→    maxQueueWaitMs: maxWaitMs,
191→  });
192→
193→  const db = getDb(env);
194→  const processingTimes: number[] = [];
195→  let successCount = 0;
196→  let errorCount = 0;
197→  let skippedCount = 0;
198→
199→  for (let i = 0; i < batch.messages.length; i++) {
200→    const msg = batch.messages[i];
201→    const msgStartTime = Date.now();
202→    const { repoId, reason } = msg.body;
203→    const queueWaitMs = Date.now() - msg.timestamp.getTime();
204→
205→    let installationId: number | null = null;
206→    try {
207→      // Look up installation for rate limit checks
208→      installationId = await getRepoInstallationId(db, repoId);
209→
210→      if (!installationId) {
211→        log("no_installation_for_repo", { batchId, repoId, reason });
212→        msg.ack();
213→        skippedCount++;
214→        continue;
215→      }
216→
217→      // Check if this installation is rate limited
218→      if (await isRateLimited(env.ENTIRE_CACHE, installationId)) {
219→        log("message_skipped_rate_limited", { batchId, repoId, installationId, reason });
220→        msg.retry();
221→        skippedCount++;
222→        continue;
223→      }
224→
225→      // Get a token for this installation
226→      const token = await getTokenForInstallation(installationId, env);
227→
228→      if (!token) {
229→        log("no_token_for_repo", { batchId, repoId, installationId, reason });
230→        // Can't sync without a token - ack to avoid infinite retries
231→        // The repo will be picked up again on next reconciliation
232→        msg.ack();
233→        skippedCount++;
234→        continue;
235→      }
236→
237→      // For user_sync, skip if repo was already synced (another job got there first)
238→      // This prevents duplicate work when multiple users log in for the same repo
239→      if (reason === "user_sync" && await db.repos.isCheckpointsSynced(repoId)) {
240→        log("skip_already_synced", { batchId, repoId, reason });
241→        msg.ack();
242→        skippedCount++;
243→        continue;
244→      }
245→
246→      const result = await traced("repo-sync-queue.processMessage", async () => {
247→        const span = trace.getActiveSpan();
248→        span?.setAttribute("queue.message_wait_ms", queueWaitMs);
249→        span?.setAttribute("github.installation_id", installationId!);
250→
251→        return await syncRepoCheckpoints(db, repoId, token);
252→      });
253→      const processingMs = Date.now() - msgStartTime;
254→      processingTimes.push(processingMs);
255→
256→      log("message_processed", {
257→        batchId,
258→        messageIndex: i + 1,
259→        totalMessages: batch.messages.length,
260→        repoId,
261→        reason,
262→        result: result.status,
263→        skipReason: result.reason,
264→        checkpoints: result.checkpointsDiscovered,
265→        queueWaitMs,
266→        processingMs,
267→        attempt: msg.attempts,
268→      });
269→
270→      msg.ack();
271→      if (result.status === "ok") {
272→        successCount++;
273→        // Notify users so frontend refreshes
274→        const usersNotified = await notifyUsersOfRepoUpdate(db, env.ENTIRE_CACHE, repoId);
275→        if (usersNotified > 0) {
276→          log("users_notified", { repoId, usersNotified });
277→        }
278→      } else if (result.status === "error") {
279→        errorCount++;
280→      } else {
281→        skippedCount++;
282→      }
283→    } catch (err) {
284→      const processingMs = Date.now() - msgStartTime;
285→      processingTimes.push(processingMs);
286→      errorCount++;
287→
288→      // Check if this is a rate limit error
289→      if (err instanceof GitHubRateLimitError) {
290→        log("rate_limit_hit", {
291→          batchId,
292→          repoId,
293→          installationId,
294→          reason,
295→          resetAt: err.resetAt
296→            ? new Date(err.resetAt * 1000).toISOString()
297→            : undefined,
298→          processingMs,
299→        });
300→
301→        // Set the rate limit marker for this installation only
302→        if (installationId) {
303→          await setRateLimitMarker(
304→            env.ENTIRE_CACHE,
305→            installationId,
306→            err.resetAt ? err.resetAt * 1000 : undefined,
307→          );
308→        }
309→
310→        // Retry only this message; continue processing remaining
311→        // (they may belong to different installations)
312→        msg.retry();
313→        continue;
314→      }
315→
316→      log("message_error", {
317→        batchId,
318→        repoId,
319→        reason,
320→        attempt: msg.attempts,
321→        processingMs,
322→        error: errorString(err),
323→      });
324→
325→      // Retry if not at max attempts (max_retries is configured in wrangler.jsonc)
326→      msg.retry();
327→    }
328→  }
329→
330→  const totalBatchTimeMs = Date.now() - batchStartTime;
331→
332→  log("batch_complete", {
333→    batchId,
334→    count: batch.messages.length,
335→    successCount,
336→    errorCount,
337→    skippedCount,
338→    totalBatchTimeMs,
339→    avgProcessingMs: avgMs(processingTimes),
340→    throughputPerMin:
341→      totalBatchTimeMs > 0
342→        ? Math.round((batch.messages.length / totalBatchTimeMs) * 60000)
343→        : 0,
344→  });
345→}
