// Strips transcript JSONL to only the fields needed by transcript parsers.
// Reduces size by ~60-80% for efficient DB storage.
//
// The parsers read:
// - type, timestamp, requestId, uuid, message.id, message.content, toolUseResult
// We drop: progress, file-history-snapshot, queue-operation, system entries
// We strip: thinking blocks, tool_use caller field, unnecessary assistant fields

// Entry types that carry no parser-relevant data
const DROPPED_TYPES = new Set([
  "progress",
  "file-history-snapshot",
  "queue-operation",
  "system",
]);

/**
 * Strip a JSONL transcript to only the fields the parsers need.
 * Processes line-by-line. Returns stripped JSONL string.
 */
export function stripTranscript(jsonlContent: string): string {
  const lines = jsonlContent.split("\n");
  const result: string[] = [];

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;

    let parsed: Record<string, unknown>;
    try {
      parsed = JSON.parse(trimmed);
    } catch {
      // Skip malformed lines
      continue;
    }

    const entryType = parsed.type as string | undefined;

    // Drop entry types that parsers ignore
    if (entryType && DROPPED_TYPES.has(entryType)) {
      continue;
    }

    const stripped = stripEntry(parsed, entryType);
    if (stripped) {
      result.push(JSON.stringify(stripped));
    }
  }

  return result.join("\n");
}

function stripEntry(
  parsed: Record<string, unknown>,
  entryType: string | undefined,
): Record<string, unknown> | null {
  if (entryType === "assistant") {
    return stripAssistantEntry(parsed);
  }

  if (entryType === "user") {
    return stripUserEntry(parsed);
  }

  // Unknown entry type — pass through with just type/timestamp/message to be safe
  // This handles future entry types or non-Claude agents
  const out: Record<string, unknown> = {};
  if (parsed.type !== undefined) out.type = parsed.type;
  if (parsed.timestamp !== undefined) out.timestamp = parsed.timestamp;
  if (parsed.message !== undefined) out.message = parsed.message;
  if (parsed.uuid !== undefined) out.uuid = parsed.uuid;
  if (parsed.requestId !== undefined) out.requestId = parsed.requestId;
  return out;
}

function stripAssistantEntry(
  parsed: Record<string, unknown>,
): Record<string, unknown> {
  const out: Record<string, unknown> = {
    type: "assistant",
  };

  if (parsed.timestamp !== undefined) out.timestamp = parsed.timestamp;
  if (parsed.requestId !== undefined) out.requestId = parsed.requestId;

  const message = parsed.message as Record<string, unknown> | undefined;
  if (message) {
    const strippedMessage: Record<string, unknown> = {};
    if (message.id !== undefined) strippedMessage.id = message.id;

    // Strip content: remove thinking blocks, strip caller from tool_use
    if (message.content !== undefined) {
      strippedMessage.content = stripAssistantContent(message.content);
    }

    out.message = strippedMessage;
  }

  return out;
}

function stripAssistantContent(content: unknown): unknown {
  // String content — keep as-is
  if (typeof content === "string") return content;

  // Array of content blocks
  if (Array.isArray(content)) {
    const stripped: unknown[] = [];
    for (const block of content) {
      if (typeof block !== "object" || block === null) {
        stripped.push(block);
        continue;
      }

      const b = block as Record<string, unknown>;

      // Drop thinking blocks
      if (b.type === "thinking" || b.type === "redacted_thinking") {
        continue;
      }

      // Strip tool_use: keep id, name, input — drop caller
      if (b.type === "tool_use") {
        const toolUse: Record<string, unknown> = {
          type: "tool_use",
        };
        if (b.id !== undefined) toolUse.id = b.id;
        if (b.name !== undefined) toolUse.name = b.name;
        if (b.input !== undefined) toolUse.input = b.input;
        stripped.push(toolUse);
        continue;
      }

      // Other block types (text, image) — keep as-is
      stripped.push(block);
    }
    return stripped;
  }

  return content;
}

function stripUserEntry(
  parsed: Record<string, unknown>,
): Record<string, unknown> {
  const out: Record<string, unknown> = {
    type: "user",
  };

  if (parsed.timestamp !== undefined) out.timestamp = parsed.timestamp;
  if (parsed.uuid !== undefined) out.uuid = parsed.uuid;

  // Keep toolUseResult but minimize it
  if (parsed.toolUseResult !== undefined) {
    out.toolUseResult = stripToolUseResult(parsed.toolUseResult);
  }

  const message = parsed.message as Record<string, unknown> | undefined;
  if (message) {
    const strippedMessage: Record<string, unknown> = {};

    if (message.content !== undefined) {
      strippedMessage.content = stripUserContent(message.content);
    }

    out.message = strippedMessage;
  }

  return out;
}

function stripUserContent(content: unknown): unknown {
  // String content — keep as-is
  if (typeof content === "string") return content;

  // Array of content blocks
  if (Array.isArray(content)) {
    const stripped: unknown[] = [];
    for (const block of content) {
      if (typeof block !== "object" || block === null) {
        stripped.push(block);
        continue;
      }

      const b = block as Record<string, unknown>;

      // tool_result: keep type and tool_use_id only (content is in toolUseResult)
      if (b.type === "tool_result") {
        const toolResult: Record<string, unknown> = {
          type: "tool_result",
        };
        if (b.tool_use_id !== undefined) toolResult.tool_use_id = b.tool_use_id;
        stripped.push(toolResult);
        continue;
      }

      // Other block types (text, image) — keep as-is
      stripped.push(block);
    }
    return stripped;
  }

  return content;
}

function stripToolUseResult(result: unknown): unknown {
  if (typeof result !== "object" || result === null) return result;

  const r = result as Record<string, unknown>;
  const out: Record<string, unknown> = {};

  if (r.type !== undefined) out.type = r.type;
  if (r.file !== undefined) out.file = r.file;
  if (r.error !== undefined) out.error = r.error;
  if (r.answers !== undefined) out.answers = r.answers;

  return out;
}

