import { describe, it, expect } from "vitest";
import { stripTranscript } from "./strip-transcript";

describe("stripTranscript", () => {
  it("returns empty string for empty input", () => {
    expect(stripTranscript("")).toBe("");
  });

  it("returns empty string for whitespace-only input", () => {
    expect(stripTranscript("  \n  \n  ")).toBe("");
  });

  it("skips malformed JSON lines", () => {
    const input = [
      "not json",
      JSON.stringify({ type: "user", timestamp: "2025-01-01T00:00:00Z", uuid: "abc", message: { content: "hello" } }),
    ].join("\n");
    const result = stripTranscript(input);
    const lines = result.split("\n");
    expect(lines).toHaveLength(1);
    const parsed = JSON.parse(lines[0]);
    expect(parsed.type).toBe("user");
  });

  it("drops progress entries", () => {
    const input = JSON.stringify({ type: "progress", data: { percent: 50 } });
    expect(stripTranscript(input)).toBe("");
  });

  it("drops system entries", () => {
    const input = JSON.stringify({ type: "system", message: "internal" });
    expect(stripTranscript(input)).toBe("");
  });

  it("drops file-history-snapshot entries", () => {
    const input = JSON.stringify({ type: "file-history-snapshot", files: [] });
    expect(stripTranscript(input)).toBe("");
  });

  it("drops queue-operation entries", () => {
    const input = JSON.stringify({ type: "queue-operation", op: "enqueue" });
    expect(stripTranscript(input)).toBe("");
  });

  it("preserves user text entries with only needed fields", () => {
    const input = JSON.stringify({
      type: "user",
      timestamp: "2025-01-01T00:00:00Z",
      uuid: "user-123",
      extraField: "should be dropped",
      message: {
        content: "Hello, please help",
        extraNested: "dropped",
      },
    });
    const result = stripTranscript(input);
    const parsed = JSON.parse(result);
    expect(parsed.type).toBe("user");
    expect(parsed.timestamp).toBe("2025-01-01T00:00:00Z");
    expect(parsed.uuid).toBe("user-123");
    expect(parsed.message.content).toBe("Hello, please help");
    expect(parsed.extraField).toBeUndefined();
    expect(parsed.message.extraNested).toBeUndefined();
  });

  it("preserves assistant entries with message.id and content", () => {
    const input = JSON.stringify({
      type: "assistant",
      timestamp: "2025-01-01T00:00:01Z",
      requestId: "req-1",
      message: {
        id: "msg-1",
        content: [
          { type: "text", text: "Here is my response" },
        ],
      },
    });
    const result = stripTranscript(input);
    const parsed = JSON.parse(result);
    expect(parsed.type).toBe("assistant");
    expect(parsed.timestamp).toBe("2025-01-01T00:00:01Z");
    expect(parsed.requestId).toBe("req-1");
    expect(parsed.message.id).toBe("msg-1");
    expect(parsed.message.content).toHaveLength(1);
    expect(parsed.message.content[0].text).toBe("Here is my response");
  });

  it("drops thinking blocks from assistant content", () => {
    const input = JSON.stringify({
      type: "assistant",
      timestamp: "2025-01-01T00:00:01Z",
      requestId: "req-1",
      message: {
        id: "msg-1",
        content: [
          { type: "thinking", thinking: "Let me think about this..." },
          { type: "text", text: "The answer is 42" },
          { type: "redacted_thinking", data: "secret" },
        ],
      },
    });
    const result = stripTranscript(input);
    const parsed = JSON.parse(result);
    expect(parsed.message.content).toHaveLength(1);
    expect(parsed.message.content[0].type).toBe("text");
    expect(parsed.message.content[0].text).toBe("The answer is 42");
  });

  it("strips caller from tool_use blocks", () => {
    const input = JSON.stringify({
      type: "assistant",
      timestamp: "2025-01-01T00:00:01Z",
      requestId: "req-1",
      message: {
        id: "msg-1",
        content: [
          {
            type: "tool_use",
            id: "tu-1",
            name: "Read",
            input: { file_path: "/src/index.ts" },
            caller: { tool_use_id: "parent-1", name: "Task" },
          },
        ],
      },
    });
    const result = stripTranscript(input);
    const parsed = JSON.parse(result);
    const toolUse = parsed.message.content[0];
    expect(toolUse.type).toBe("tool_use");
    expect(toolUse.id).toBe("tu-1");
    expect(toolUse.name).toBe("Read");
    expect(toolUse.input).toEqual({ file_path: "/src/index.ts" });
    expect(toolUse.caller).toBeUndefined();
  });

  it("minimizes user tool_result content blocks", () => {
    const input = JSON.stringify({
      type: "user",
      timestamp: "2025-01-01T00:00:02Z",
      uuid: "user-2",
      toolUseResult: {
        type: "text",
        file: { filePath: "/src/index.ts", numLines: 42 },
        output: "file content here which is large",
      },
      message: {
        content: [
          {
            type: "tool_result",
            tool_use_id: "tu-1",
            content: "file content here which is large",
          },
        ],
      },
    });
    const result = stripTranscript(input);
    const parsed = JSON.parse(result);
    // tool_result block should only have type and tool_use_id
    const block = parsed.message.content[0];
    expect(block.type).toBe("tool_result");
    expect(block.tool_use_id).toBe("tu-1");
    expect(block.content).toBeUndefined();
    // toolUseResult should keep type and file, drop output
    expect(parsed.toolUseResult.type).toBe("text");
    expect(parsed.toolUseResult.file).toEqual({ filePath: "/src/index.ts", numLines: 42 });
    expect(parsed.toolUseResult.output).toBeUndefined();
  });

  it("preserves toolUseResult error field", () => {
    const input = JSON.stringify({
      type: "user",
      timestamp: "2025-01-01T00:00:02Z",
      toolUseResult: {
        type: "error",
        error: "file not found",
        output: "some debug info",
      },
      message: { content: [{ type: "tool_result", tool_use_id: "tu-2" }] },
    });
    const result = stripTranscript(input);
    const parsed = JSON.parse(result);
    expect(parsed.toolUseResult.type).toBe("error");
    expect(parsed.toolUseResult.error).toBe("file not found");
    expect(parsed.toolUseResult.output).toBeUndefined();
  });

  it("preserves toolUseResult answers field", () => {
    const input = JSON.stringify({
      type: "user",
      timestamp: "2025-01-01T00:00:02Z",
      toolUseResult: {
        type: "text",
        answers: { q1: "yes", q2: "no" },
        output: "some data",
      },
      message: { content: [{ type: "tool_result", tool_use_id: "tu-3" }] },
    });
    const result = stripTranscript(input);
    const parsed = JSON.parse(result);
    expect(parsed.toolUseResult.answers).toEqual({ q1: "yes", q2: "no" });
    expect(parsed.toolUseResult.output).toBeUndefined();
  });

  it("handles multi-line JSONL with mixed entry types", () => {
    const lines = [
      JSON.stringify({ type: "system", message: "init" }),
      JSON.stringify({ type: "user", timestamp: "t1", uuid: "u1", message: { content: "hi" } }),
      JSON.stringify({ type: "progress", data: {} }),
      JSON.stringify({ type: "assistant", timestamp: "t2", requestId: "r1", message: { id: "m1", content: "hello" } }),
      JSON.stringify({ type: "file-history-snapshot", files: ["a.ts"] }),
      JSON.stringify({ type: "user", timestamp: "t3", uuid: "u2", message: { content: "thanks" } }),
    ];
    const result = stripTranscript(lines.join("\n"));
    const resultLines = result.split("\n");
    expect(resultLines).toHaveLength(3); // user, assistant, user
    expect(JSON.parse(resultLines[0]).type).toBe("user");
    expect(JSON.parse(resultLines[1]).type).toBe("assistant");
    expect(JSON.parse(resultLines[2]).type).toBe("user");
  });

  it("preserves assistant string content unchanged", () => {
    const input = JSON.stringify({
      type: "assistant",
      timestamp: "t1",
      requestId: "r1",
      message: { id: "m1", content: "plain text response" },
    });
    const result = stripTranscript(input);
    const parsed = JSON.parse(result);
    expect(parsed.message.content).toBe("plain text response");
  });

  it("preserves image blocks in assistant content", () => {
    const input = JSON.stringify({
      type: "assistant",
      timestamp: "t1",
      requestId: "r1",
      message: {
        id: "m1",
        content: [
          { type: "image", source: { type: "base64", data: "abc123", media_type: "image/png" } },
          { type: "text", text: "Here is the image" },
        ],
      },
    });
    const result = stripTranscript(input);
    const parsed = JSON.parse(result);
    expect(parsed.message.content).toHaveLength(2);
    expect(parsed.message.content[0].type).toBe("image");
    expect(parsed.message.content[0].source.data).toBe("abc123");
  });

  it("stripped transcript still parses correctly", () => {
    // Simulate a realistic multi-turn transcript
    const transcript = [
      JSON.stringify({
        type: "user",
        timestamp: "2025-01-01T00:00:00Z",
        uuid: "u1",
        message: { content: "What is 2+2?" },
      }),
      JSON.stringify({
        type: "assistant",
        timestamp: "2025-01-01T00:00:01Z",
        requestId: "r1",
        message: {
          id: "m1",
          content: [
            { type: "thinking", thinking: "Simple arithmetic..." },
            { type: "text", text: "2+2 = 4" },
          ],
        },
      }),
      JSON.stringify({
        type: "assistant",
        timestamp: "2025-01-01T00:00:02Z",
        requestId: "r1",
        message: {
          id: "m1",
          content: [
            { type: "thinking", thinking: "Simple arithmetic..." },
            { type: "text", text: "2+2 = 4. Is there anything else?" },
          ],
        },
      }),
    ].join("\n");

    const stripped = stripTranscript(transcript);

    // Verify each line is valid JSON
    const lines = stripped.split("\n");
    for (const line of lines) {
      expect(() => JSON.parse(line)).not.toThrow();
    }

    // Verify structure is maintained for parser consumption
    expect(lines).toHaveLength(3);
    const user = JSON.parse(lines[0]);
    expect(user.type).toBe("user");
    expect(user.uuid).toBe("u1");
    expect(user.message.content).toBe("What is 2+2?");

    const assistant = JSON.parse(lines[2]); // Last assistant (streaming dedup would pick this)
    expect(assistant.type).toBe("assistant");
    expect(assistant.requestId).toBe("r1");
    expect(assistant.message.content).toHaveLength(1); // thinking dropped
    expect(assistant.message.content[0].text).toContain("2+2 = 4");
  });
});

