// Search index queue consumer
// Processes checkpoint indexing messages for Turbopuffer vector search

import type { Env } from "../env";
import { getDb } from "./db";
import type { Db } from "./db/db-types";
import { indexCheckpoints } from "./turbopuffer";
import { avgMs, generateBatchId } from "./telemetry";
import { getInstallationToken } from "./token";
import { fetchFileAtCommit } from "./github";
import { getParserForAgent } from "./transcript-parsers/registry";
import { CHECKPOINT_BRANCH } from "./constants";
import { stripTranscript } from "./strip-transcript";

const MAX_TRANSCRIPT_CHARS = 200_000;
const TRANSCRIPT_CONCURRENCY = 10;

// Queue message sent after checkpoint data is upserted into PlanetScale
export interface SearchIndexMessage {
  repoId: string;
  checkpointIds: string[];
  queuedAt: string;
}

// Type guard to check if a message is a SearchIndexMessage
export function isSearchIndexMessage(
  msg: unknown,
): msg is SearchIndexMessage {
  return (
    typeof msg === "object" &&
    msg !== null &&
    "repoId" in msg &&
    "checkpointIds" in msg &&
    "queuedAt" in msg &&
    typeof (msg as SearchIndexMessage).repoId === "string" &&
    Array.isArray((msg as SearchIndexMessage).checkpointIds)
  );
}

// Log with consistent prefix
function log(event: string, data: Record<string, unknown>): void {
  console.log(`[search-index-queue] ${event}`, JSON.stringify(data));
}

// Fetch transcript from GitHub, strip it, and return the stripped JSONL
// Returns a per-session map: { "0": "stripped jsonl...", "1": "..." }
async function fetchAndStripTranscript(
  repoFullName: string,
  checkpointId: string,
  sessionCount: number,
  token: string,
): Promise<Record<string, string> | null> {
  try {
    const folder = `${checkpointId.slice(0, 2)}/${checkpointId.slice(2)}`;
    const sessions: Record<string, string> = {};
    const count = Math.max(sessionCount, 1);

    for (let i = 0; i < count; i++) {
      const path = `${folder}/${i}/full.jsonl`;
      const content = await fetchFileAtCommit(repoFullName, path, CHECKPOINT_BRANCH, token);
      if (content) {
        sessions[String(i)] = stripTranscript(content);
      }
    }

    return Object.keys(sessions).length > 0 ? sessions : null;
  } catch {
    return null;
  }
}

// Parse stripped transcript JSONL into a searchable text excerpt
function parseTranscriptExcerpt(
  strippedJsonl: string,
  agent: string,
): string | null {
  try {
    const parser = getParserForAgent(agent);
    const result = parser.parse(strippedJsonl);
    if (result.messages.length === 0) return null;

    const parts: string[] = [];
    let charsUsed = 0;

    for (const msg of result.messages) {
      if (charsUsed >= MAX_TRANSCRIPT_CHARS) break;
      if (msg.role === "assistant" && msg.toolCalls?.length && !msg.content.trim()) continue;

      const remaining = MAX_TRANSCRIPT_CHARS - charsUsed;
      const text = msg.content.slice(0, remaining);
      parts.push(`[${msg.role}]: ${text}`);
      charsUsed += text.length;
    }

    return parts.join("\n") || null;
  } catch {
    return null;
  }
}

// Ensure transcripts are stored in DB, fetching from GitHub if needed.
// Returns a map of checkpoint_id → searchable transcript text.
async function ensureTranscriptsStored(
  db: Db,
  repoId: string,
  repoFullName: string,
  installationId: string | null,
  checkpoints: Array<{ checkpoint_id: string; agent: string; session_count: number }>,
  env: Env,
  batchId: string,
): Promise<Map<string, string | null>> {
  const transcripts = new Map<string, string | null>();

  // Check which checkpoints already have transcripts in DB
  const dbResults = new Map<string, Record<string, string> | null>();
  const missingIds: string[] = [];

  for (const cp of checkpoints) {
    const row = await db.checkpoints.getTranscript(repoId, cp.checkpoint_id);
    if (row?.transcript_stripped) {
      try {
        const parsed = JSON.parse(row.transcript_stripped) as Record<string, string>;
        dbResults.set(cp.checkpoint_id, parsed);
      } catch {
        missingIds.push(cp.checkpoint_id);
      }
    } else {
      missingIds.push(cp.checkpoint_id);
    }
  }

  if (dbResults.size > 0) {
    log("transcripts_from_db", { batchId, repoId, count: dbResults.size });
  }

  // Parse DB transcripts into searchable text
  for (const cp of checkpoints) {
    const sessions = dbResults.get(cp.checkpoint_id);
    if (sessions) {
      // Use session 0 for search indexing (primary session)
      const primaryJsonl = sessions["0"];
      if (primaryJsonl) {
        transcripts.set(cp.checkpoint_id, parseTranscriptExcerpt(primaryJsonl, cp.agent));
      }
    }
  }

  // Fetch missing transcripts from GitHub
  if (missingIds.length > 0 && installationId) {
    try {
      const token = await getInstallationToken(
        Number(installationId),
        { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
        env.ENTIRE_CACHE,
      );

      const missingCheckpoints = checkpoints.filter((cp) => missingIds.includes(cp.checkpoint_id));
      const dbUpdates: Array<{ checkpoint_id: string; transcript_stripped: string }> = [];

      // Fetch in parallel with concurrency limit
      for (let i = 0; i < missingCheckpoints.length; i += TRANSCRIPT_CONCURRENCY) {
        const batch = missingCheckpoints.slice(i, i + TRANSCRIPT_CONCURRENCY);
        const results = await Promise.all(
          batch.map((cp) =>
            fetchAndStripTranscript(repoFullName, cp.checkpoint_id, cp.session_count, token),
          ),
        );

        for (let j = 0; j < results.length; j++) {
          const cp = batch[j];
          const sessions = results[j];
          if (sessions) {
            dbUpdates.push({
              checkpoint_id: cp.checkpoint_id,
              transcript_stripped: JSON.stringify(sessions),
            });

            // Parse for search indexing
            const primaryJsonl = sessions["0"];
            if (primaryJsonl) {
              transcripts.set(cp.checkpoint_id, parseTranscriptExcerpt(primaryJsonl, cp.agent));
            }
          }
        }
      }

      // Store stripped transcripts in DB
      if (dbUpdates.length > 0) {
        const stored = await db.checkpoints.updateTranscriptBatch(repoId, dbUpdates);
        log("transcripts_stored", { batchId, repoId, stored, attempted: dbUpdates.length });
      }
    } catch (err) {
      log("transcript_fetch_error", {
        batchId,
        repoId,
        error: err instanceof Error ? err.message : String(err),
      });
      // Continue without transcripts — prompt/commit/files still get indexed
    }
  }

  return transcripts;
}

// Process a batch of search index messages
export async function processSearchIndexBatch(
  batch: MessageBatch<SearchIndexMessage>,
  env: Env,
): Promise<void> {
  const batchStartTime = Date.now();
  const batchId = generateBatchId();

  const queueWaitTimes = batch.messages.map(
    (msg) => Date.now() - msg.timestamp.getTime(),
  );
  const maxWaitMs = queueWaitTimes.length > 0 ? Math.max(...queueWaitTimes) : 0;

  log("batch_started", {
    batchId,
    queue: batch.queue,
    count: batch.messages.length,
    avgQueueWaitMs: avgMs(queueWaitTimes),
    maxQueueWaitMs: maxWaitMs,
  });

  const processingTimes: number[] = [];
  let successCount = 0;
  let errorCount = 0;
  let skippedCount = 0;

  for (const msg of batch.messages) {
    const msgStartTime = Date.now();
    const { repoId, checkpointIds } = msg.body;

    // Early return if API keys are missing — don't retry messages that can never succeed
    if (!env.TURBOPUFFER_API_KEY || !env.OPENAI_API_KEY) {
      log("skip_missing_api_keys", {
        batchId,
        repoId,
        hasTurbopuffer: !!env.TURBOPUFFER_API_KEY,
        hasOpenai: !!env.OPENAI_API_KEY,
      });
      msg.ack();
      skippedCount++;
      continue;
    }

    try {
      const db = getDb(env);

      const repo = await db.repos.getById(repoId);
      if (!repo) {
        log("skip_repo_not_found", { batchId, repoId });
        msg.ack();
        skippedCount++;
        continue;
      }

      const checkpoints = await db.checkpoints.getByIds(repoId, checkpointIds);

      if (checkpoints.length === 0) {
        log("skip_no_checkpoints", { batchId, repoId, requestedIds: checkpointIds.length });
        msg.ack();
        skippedCount++;
        continue;
      }

      // Ensure transcripts are stored in DB, fetching from GitHub if needed
      const transcripts = await ensureTranscriptsStored(
        db,
        repoId,
        repo.full_name,
        repo.installation_id,
        checkpoints.map((cp) => ({
          checkpoint_id: cp.checkpoint_id,
          agent: cp.agent ?? "Claude Code",
          session_count: cp.session_count ?? 1,
        })),
        env,
        batchId,
      );

      const indexed = await indexCheckpoints(
        env.TURBOPUFFER_API_KEY,
        env.OPENAI_API_KEY,
        repo.github_id,
        checkpoints.map((cp) => ({
          checkpoint_id: cp.checkpoint_id,
          branch: cp.branch,
          agent: cp.agent,
          commit_author_username: cp.commit_author_username,
          created_at: cp.created_at,
          commit_sha: cp.commit_sha,
          commit_message: cp.commit_message,
          prompt: cp.prompt,
          files_touched: cp.files_touched,
          transcript: transcripts.get(cp.checkpoint_id) ?? null,
        })),
      );

      const processingMs = Date.now() - msgStartTime;
      processingTimes.push(processingMs);

      log("message_processed", {
        batchId,
        repoId,
        requested: checkpointIds.length,
        found: checkpoints.length,
        indexed,
        processingMs,
        attempt: msg.attempts,
      });

      msg.ack();
      successCount++;
    } catch (err) {
      const processingMs = Date.now() - msgStartTime;
      processingTimes.push(processingMs);
      errorCount++;

      log("message_error", {
        batchId,
        repoId,
        checkpointCount: checkpointIds.length,
        attempt: msg.attempts,
        processingMs,
        error: err instanceof Error ? err.message : String(err),
      });

      // Retry on transient failures (max_retries configured in wrangler.jsonc)
      msg.retry();
    }
  }

  const totalBatchTimeMs = Date.now() - batchStartTime;

  log("batch_complete", {
    batchId,
    count: batch.messages.length,
    successCount,
    errorCount,
    skippedCount,
    totalBatchTimeMs,
    avgProcessingMs: avgMs(processingTimes),
    throughputPerMin:
      totalBatchTimeMs > 0
        ? Math.round((batch.messages.length / totalBatchTimeMs) * 60000)
        : 0,
  });
}

