// Try DB-stored stripped transcript before fetching from GitHub
try {
  const dbRow = await db.checkpoints.getTranscript(repoAccess.id, checkpointId);
  if (dbRow?.transcript_stripped) {
    const strippedSessions = JSON.parse(dbRow.transcript_stripped) as Record<string, string>;
    const dbSessionsMeta: Array<{
      agent: string;
      sessionId: string;
      transcriptIdentifierAtStart: string | null;
      tokenUsage?: { inputTokens: number; outputTokens: number };
      attribution?: SessionAttribution;
    }> = [];

    // Parse per-session metadata from DB sessions column
    if (dbRow.sessions) {
      try {
        const sessionsInfo = JSON.parse(dbRow.sessions) as Array<{
          agent?: string;
          sessionId?: string;
          transcriptIdentifierAtStart?: string;
          tokenUsage?: { inputTokens: number; outputTokens: number; cacheCreationTokens?: number; cacheReadTokens?: number; apiCallCount?: number };
          attribution?: { calculatedAt: string; agentLines: number; humanAdded: number; humanModified: number; humanRemoved: number; totalCommitted: number; agentPercentage: number };
        }>;
        for (const s of sessionsInfo) {
          dbSessionsMeta.push({
            agent: s.agent ?? "Claude Code",
            sessionId: s.sessionId ?? "0",
            transcriptIdentifierAtStart: s.transcriptIdentifierAtStart ?? null,
            tokenUsage: s.tokenUsage ? {
              inputTokens: s.tokenUsage.inputTokens ?? 0,
              outputTokens: s.tokenUsage.outputTokens ?? 0,
            } : undefined,
            attribution: s.attribution ? {
              calculatedAt: s.attribution.calculatedAt ?? "",
              agentLines: s.attribution.agentLines ?? 0,
              humanAdded: s.attribution.humanAdded ?? 0,
              humanModified: s.attribution.humanModified ?? 0,
              humanRemoved: s.attribution.humanRemoved ?? 0,
              totalCommitted: s.attribution.totalCommitted ?? 0,
              agentPercentage: s.attribution.agentPercentage ?? 0,
            } : undefined,
          });
        }
      } catch {
        // Invalid sessions JSON, fall through to GitHub
      }
    }

    const dbParsedSessions: SessionTranscript[] = [];
    const sessionIndices = Object.keys(strippedSessions).sort();
    for (const idx of sessionIndices) {
      const jsonl = strippedSessions[idx];
      if (!jsonl) continue;
      const meta = dbSessionsMeta[Number(idx)];
      const agent = meta?.agent ?? "Claude Code";
      const parseResult = getParserForAgent(agent).parse(jsonl);
      const messages = filterRelevantMessages(
        parseResult.messages,
        meta?.transcriptIdentifierAtStart ?? null,
      );
      dbParsedSessions.push({
        sessionId: meta?.sessionId ?? idx,
        agent,
        messages,
        transcriptIdentifierAtStart: meta?.transcriptIdentifierAtStart ?? null,
        tokenUsage: meta?.tokenUsage,
        attribution: meta?.attribution,
        parsingFallback: parseResult.isFallback || undefined,
        parsingWarning: parseResult.warning,
      });
    }

    if (dbParsedSessions.length > 0) {
      // Cache to KV for subsequent requests
      const cacheData: CachedTranscript = {
        checkpointId,
        sessions: dbParsedSessions,
        cached_at: new Date().toISOString(),
      };
      await c.env.ENTIRE_CACHE.put(cacheKey, JSON.stringify(cacheData), {
        expirationTtl: TRANSCRIPT_CACHE_TTL_SECONDS,
      });

      return c.json({
        checkpointId,
        sessions: dbParsedSessions,
        from_cache: false,
      });
    }
  }
} catch {
  // DB lookup failed, fall through to GitHub
}

