        }
      }

      const dbParsedSessions: SessionTranscript[] = [];
      const sessionIndices = Object.keys(strippedSessions).sort();
      for (const idx of sessionIndices) {
        const jsonl = strippedSessions[idx];
        if (!jsonl) continue;
        const meta = dbSessionsMeta[Number(idx)];
        const agent = meta?.agent ?? "Claude Code";
        const parseResult = getParserForAgent(agent).parse(jsonl);
        const messages = filterRelevantMessages(
          parseResult.messages,
          meta?.transcriptIdentifierAtStart ?? null,
        );
        dbParsedSessions.push({
          sessionId: meta?.sessionId ?? idx,
          agent,
          messages,
          transcriptIdentifierAtStart: meta?.transcriptIdentifierAtStart ?? null,
          tokenUsage: meta?.tokenUsage,
          attribution: meta?.attribution,
          parsingFallback: parseResult.isFallback || undefined,
          parsingWarning: parseResult.warning,
        });
      }

      if (dbParsedSessions.length > 0) {
        // Cache to KV for subsequent requests
        const cacheData: CachedTranscript = {
          checkpointId,
          sessions: dbParsedSessions,
          cached_at: new Date().toISOString(),
        };
        await c.env.ENTIRE_CACHE.put(cacheKey, JSON.stringify(cacheData), {
          expirationTtl: TRANSCRIPT_CACHE_TTL_SECONDS,
        });

        return c.json({
          checkpointId,
          sessions: dbParsedSessions,
          from_cache: false,
        });
      }
    }
  }
