101→// Ensure transcripts are stored in DB, fetching from GitHub if needed.
102→// Returns a map of checkpoint_id → searchable transcript text.
103→async function ensureTranscriptsStored(
104→  db: Db,
105→  repoId: string,
106→  repoFullName: string,
107→  installationId: string | null,
108→  checkpoints: Array<{ checkpoint_id: string; agent: string; session_count: number }>,
109→  env: Env,
110→  batchId: string,
111→): Promise<Map<string, string | null>> {
112→  const transcripts = new Map<string, string | null>();
113→
114→  // Check which checkpoints already have transcripts in DB
115→  const dbResults = new Map<string, Record<string, string> | null>();
116→  const missingIds: string[] = [];
117→
118→  for (const cp of checkpoints) {
119→    const row = await db.checkpoints.getTranscript(repoId, cp.checkpoint_id);
120→    if (row?.transcript_stripped) {
121→      try {
122→        const parsed = JSON.parse(row.transcript_stripped) as Record<string, string>;
123→        dbResults.set(cp.checkpoint_id, parsed);
124→      } catch {
125→        missingIds.push(cp.checkpoint_id);
126→      }
127→    } else {
128→      missingIds.push(cp.checkpoint_id);
129→    }
130→  }
131→
132→  if (dbResults.size > 0) {
133→    log("transcripts_from_db", { batchId, repoId, count: dbResults.size });
134→  }
135→
136→  // Parse DB transcripts into searchable text
137→  for (const cp of checkpoints) {
138→    const sessions = dbResults.get(cp.checkpoint_id);
139→    if (sessions) {
140→      // Use session 0 for search indexing (primary session)
141→      const primaryJsonl = sessions["0"];
142→      if (primaryJsonl) {
143→        transcripts.set(cp.checkpoint_id, parseTranscriptExcerpt(primaryJsonl, cp.agent));
144→      }
145→    }
146→  }
147→
148→  // Fetch missing transcripts from GitHub
149→  if (missingIds.length > 0 && installationId) {
150→    try {
151→      const token = await getInstallationToken(
152→        Number(installationId),
153→        { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
154→        env.ENTIRE_CACHE,
155→      );
156→
157→      const missingCheckpoints = checkpoints.filter((cp) => missingIds.includes(cp.checkpoint_id));
158→      const dbUpdates: Array<{ checkpoint_id: string; transcript_stripped: string }> = [];
159→
160→      // Fetch in parallel with concurrency limit
161→      for (let i = 0; i < missingCheckpoints.length; i += TRANSCRIPT_CONCURRENCY) {
162→        const batch = missingCheckpoints.slice(i, i + TRANSCRIPT_CONCURRENCY);
163→        const results = await Promise.all(
164→          batch.map((cp) =>
165→            fetchAndStripTranscript(repoFullName, cp.checkpoint_id, cp.session_count, token),
166→          ),
167→        );
168→
169→        for (let j = 0; j < results.length; j++) {
170→          const cp = batch[j];
171→          const sessions = results[j];
172→          if (sessions) {
173→            dbUpdates.push({
174→              checkpoint_id: cp.checkpoint_id,
175→              transcript_stripped: JSON.stringify(sessions),
176→            });
177→
178→            // Parse for search indexing
179→            const primaryJsonl = sessions["0"];
180→            if (primaryJsonl) {
181→              transcripts.set(cp.checkpoint_id, parseTranscriptExcerpt(primaryJsonl, cp.agent));
182→            }
183→          }
184→        }
185→      }
186→
187→      // Store stripped transcripts in DB
188→      if (dbUpdates.length > 0) {
189→        const stored = await db.checkpoints.updateTranscriptBatch(repoId, dbUpdates);
190→        log("transcripts_stored", { batchId, repoId, stored, attempted: dbUpdates.length });
191→      }
192→    } catch (err) {
193→      log("transcript_fetch_error", {
194→        batchId,
195→        repoId,
196→        error: err instanceof Error ? err.message : String(err),
197→      });
198→      // Continue without transcripts — prompt/commit/files still get indexed
199→    }
200→  }
201→
202→  return transcripts;
203→}
