 42→export function truncateToBytes(str: string | null, maxBytes: number): string | null {
 43→  if (str === null) return null;
 44→  if (str.length <= maxBytes) return str;
 45→  const encoder = new TextEncoder();
 46→  const encoded = encoder.encode(str);
 47→  if (encoded.length <= maxBytes) return str;
 48→  const truncated = encoded.slice(0, maxBytes);
 49→  const decoder = new TextDecoder();
 50→  return decoder.decode(truncated);
 51→}
