 75→// Hash checkpoint_id to a deterministic numeric ID for Turbopuffer
 76→// Uses FNV-1a 32-bit hash for fast, well-distributed IDs
 77→export function hashToNumericId(checkpointId: string): number {
 78→  let hash = 0x811c9dc5; // FNV offset basis
 79→  for (let i = 0; i < checkpointId.length; i++) {
 80→    hash ^= checkpointId.charCodeAt(i);
 81→    hash = Math.imul(hash, 0x01000193); // FNV prime
 82→  }
 83→  return hash >>> 0; // unsigned 32-bit
 84→}
