export async function getCheckpointTranscriptBatch(
  db: Kysely<DB>,
  repoId: string,
  checkpointIds: string[],
): Promise<Array<{ checkpoint_id: string; transcript_stripped: string | null }>> {
  if (checkpointIds.length === 0) return [];

  const rows = await db
    .selectFrom("repo_checkpoints")
